const Home = () => {
  const [activeCategory, setActiveCategory] = useState('All');
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState('latest');
  const [favorites, setFavorites] = useState(new Set());
  const [loading, setLoading] = useState(false);
  const [failedImages, setFailedImages] = useState(new Set());

  const handleImageError = (productId) => {
    setFailedImages((prev) => new Set([...prev, productId]));
  };

  const getImageUrl = (product) => {
    if (failedImages.has(product.id) || !product.image) return FALLBACK_IMAGE;
    return product.image;
  };

  const filteredProducts = useMemo(() => {
    let result = products.filter((product) => {
      const matchesCategory = activeCategory === 'All' || product.category === activeCategory;
      const matchesSearch = product.title.toLowerCase().includes(search.toLowerCase());
      return matchesCategory && matchesSearch;
    });
    if (sortBy === 'price-low') result.sort((a, b) => parseInt(a.price) - parseInt(b.price));
    else if (sortBy === 'price-high') result.sort((a, b) => parseInt(b.price) - parseInt(a.price));
    return result;
  }, [activeCategory, search, sortBy]);

  const toggleFavorite = (productId) => {
    setFavorites((prev) => {
      const newFavorites = new Set(prev);
      if (newFavorites.has(productId)) newFavorites.delete(productId);
      else newFavorites.add(productId);
      return newFavorites;
    });
  };

  useEffect(() => {
    setLoading(true);
    const timer = setTimeout(() => setLoading(false), 800);
    return () => clearTimeout(timer);
  }, [activeCategory, search]);

  return (
    <main className="page-shell">

      {/* ===== HERO SECTION ===== */}
      <section className="hero-panel">
        <div className="hero-trust-badge">
          🎓 Trusted by 10,000+ Students
        </div>

        <h1>Your Campus, Your Marketplace</h1>

        <p className="hero-sub">
          Buy and sell textbooks, tech, furniture & more from students nearby
        </p>

        <div className="hero-search-bar">
          <span>🔍</span>
          <input
            type="search"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search for anything... textbooks, laptops, furniture"
          />
        </div>

        <div className="hero-chips">
          {categories.slice(0, 7).map((cat) => (
            <button
              key={cat.name}
              className={`hero-chip ${activeCategory === cat.name ? 'active' : ''}`}
              onClick={() => setActiveCategory(cat.name)}
              type="button"
            >
              <span>{cat.icon}</span>
              <span>{cat.name}</span>
            </button>
          ))}
        </div>
      </section>

      {/* ===== ALL CATEGORIES SCROLL ===== */}
      <section className="categories-section">
        <div className="categories-scroll-container">
          <div className="categories-row">
            {categories.map((cat) => (
              <button
                key={cat.name}
                className={`category-chip ${activeCategory === cat.name ? 'active' : ''}`}
                onClick={() => setActiveCategory(cat.name)}
                type="button"
                title={cat.name}
              >
                <span className="category-icon">{cat.icon}</span>
                <span className="category-label">{cat.name}</span>
              </button>
            ))}
          </div>
        </div>
      </section>

      {/* ===== TOOLBAR ===== */}
      <section className="marketplace-toolbar">
        <div className="toolbar-left">
          <select
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value)}
            className="sort-dropdown"
          >
            <option value="latest">Latest</option>
            <option value="price-low">Price: Low to High</option>
            <option value="price-high">Price: High to Low</option>
          </select>

          <button
            type="button"
            className={`favorites-toggle ${favorites.size > 0 ? 'active' : ''}`}
          >
            <span className="heart-icon">❤️</span>
            <span>{favorites.size > 0 ? favorites.size : 'Favorites'}</span>
          </button>
        </div>

        <div>
          <span style={{ color: '#0f766e', fontWeight: '600', fontSize: '14px' }}>
            {filteredProducts.length} result{filteredProducts.length !== 1 ? 's' : ''}
          </span>
        </div>
      </section>

      {/* ===== LOADING SKELETON ===== */}
      {loading && (
        <section className="products-grid">
          {[1, 2, 3, 4, 5, 6].map((i) => (
            <div key={i} className="skeleton-card">
              <div className="skeleton-image"></div>
              <div className="skeleton-body">
                <div className="skeleton-title"></div>
                <div className="skeleton-price"></div>
                <div className="skeleton-category"></div>
              </div>
            </div>
          ))}
        </section>
      )}

      {/* ===== PRODUCTS GRID ===== */}
      {!loading && filteredProducts.length > 0 ? (
        <section className="products-grid">
          {filteredProducts.map((product) => (
            <article key={product.id} className="product-card">
              <div className="card-image">
                <img
                  src={getImageUrl(product)}
                  alt={product.title}
                  className="product-image"
                  onError={() => handleImageError(product.id)}
                  loading="lazy"
                />
                <span className="badge">{product.badge}</span>
                <button
                  className="bookmark-icon"
                  type="button"
                  onClick={() => toggleFavorite(product.id)}
                  style={{
                    background: favorites.has(product.id)
                      ? 'linear-gradient(135deg, #ec4899, #f43f5e)'
                      : 'rgba(255,255,255,0.9)',
                    transform: favorites.has(product.id) ? 'scale(1.1)' : 'scale(1)',
                    transition: 'all 0.2s ease'
                  }}
                >
                  {favorites.has(product.id) ? '❤️' : '🤍'}
                </button>
              </div>
              <div className="card-body">
                <h3>{product.title}</h3>
                <p className="card-price">₹{product.price}</p>
                <div className="card-meta">
                  <span className="card-category">{product.category}</span>
                  <Link to={`/product/${product.id}`} className="card-link">
                    View
                  </Link>
                </div>
              </div>
            </article>
          ))}
        </section>
      ) : !loading ? (
        <section className="empty-state">
          <div className="empty-state-icon">📦</div>
          <h2 className="empty-state-title">No products found</h2>
          <p className="empty-state-description">
            {search
              ? `No results for "${search}". Try adjusting your search.`
              : activeCategory !== 'All'
              ? `No products in ${activeCategory}. Try another category!`
              : 'No products available right now. Be the first to post one!'}
          </p>
          {search || activeCategory !== 'All' ? (
            <button
              type="button"
              className="empty-state-action"
              onClick={() => { setSearch(''); setActiveCategory('All'); }}
            >
              ← Clear filters
            </button>
          ) : (
            <Link to="/sell" className="empty-state-action">
              ➕ Post first item
            </Link>
          )}
        </section>
      ) : null}

    </main>
  );
};

export default Home;
